    "h_statements": [
      {
        "code": "H332",
        "text": "(가스, 증기, 분진, 미스트) 흡입하면 유해함.",
        "line": "p1:L26"
      },
      {
        "code": "H314",
        "text": "피부에 심한 화상 또는 눈에 손상을 일으킴.",
        "line": "p1:L27"
      },
      {
        "code": "H318",
        "text": "눈에 심한 손상을 일으킴.",
        "line": "p1:L28"
      },
      {
        "code": "H350",
        "text": "암을 일으킬 수 있음.",
        "line": "p1:L29"
      },
      {
        "code": "H341",
        "text": "유전적인 결함을 일으킬 것으로 의심됨.",
        "line": "p1:L30"
      },
      {
        "code": "H370",
        "text": "장기(호흡기계)에 손상을 일으킴.",
        "line": "p1:L31"
      },
      {
        "code": "H372",
        "text": "장기적이고 반복적인 노출로 장기(조혈계, 신장, 중추 신경계, 말초신경계, 심혈관계, 면역계, 호흡기계)에 손상을 일으킴.",
        "line": "p1:L32"
      }
    ],
    "p_statements": [
      {
        "code": "P261",
        "type": "예방",
        "text": "분진·흄·가스·미스트·증기·스프레이의 흡입을 피하시오.",
        "line": "p2:L4"
      },
      {
        "code": "P271",
        "type": "예방",
        "text": "옥외 또는 환기가 잘 되는 곳에서만 취급하시오.",
        "line": "p2:L4"
      },
      {
        "code": "P260",
        "type": "예방",
        "text": "분진·흄·가스·미스트·증기·스프레이를 흡입하지 마시오.",
        "line": "p2:L5"
      },
      {
        "code": "P264",
        "type": "예방",
        "text": "취급 후에는 손을 철저히 씻으시오.",
        "line": "p2:L6"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "보호장갑·보호의·보안경·안면보호구를 착용하시오.",
        "line": "p2:L6"
      },
      {
        "code": "P201",
        "type": "예방",
        "text": "사용 전 취급 설명서를 확보하시오.",
        "line": "p2:L7"
      },
      {
        "code": "P202",
        "type": "예방",
        "text": "모든 안전 예방조치 문구를 읽고 이해하기 전에는 취급하지 마시오.",
        "line": "p2:L7"
      },
      {
        "code": "P281",
        "type": "예방",
        "text": "적절한 개인 보호구를 착용하시오.",
        "line": "p2:L7"
      },
      {
        "code": "P270",
        "type": "예방",
        "text": "이 제품을 사용할 때에는 먹거리, 마시거나 흡연하지 마시오.",
        "line": "p2:L7"
      },
      {
        "code": "P304+P340",
        "type": "대응",
        "text": "흡입하면 신선한 공기가 있는 곳으로 옮기고 호흡하기 쉬운 자세로 안정을 취하시오.",
        "line": "p2:L8"
      },
      {
        "code": "P312",
        "type": "대응",
        "text": "불편함을 느끼면 의료기관(의사)의 진찰을 받으시오.",
        "line": "p2:L9"
      },
      {
        "code": "P301+P330+P331",
        "type": "대응",
        "text": "삼켰다면 입을 씻어내시오. 토하게 하려 하지 마시오.",
        "line": "p2:L10"
      },
      {
        "code": "P303+P361+P353",
        "type": "대응",
        "text": "피부(또는 머리카락)에 묻으면 오염된 모든 의복은 벗거나 제거하시오. 피부를 물로 씻으시오/샤워하시오.",
        "line": "p2:L11"
      },
      {
        "code": "P363",
        "type": "대응",
        "text": "다시 사용전 오염된 의류는 세척하시오.",
        "line": "p2:L12"
      },
      {
        "code": "P310",
        "type": "대응",
        "text": "즉시 의료기관(의사)의 진찰을 받으시오.",
        "line": "p2:L13"
      },
      {
        "code": "P321",
        "type": "대응",
        "text": "해독제나 특정 세척제가 있는 경우 처치를 하시오.",
        "line": "p2:L13"
      },
      {
        "code": "P305+P351+P338",
        "type": "대응",
        "text": "눈에 묻으면 몇 분간 물로 조심해서 씻으시오. 가능하면 콘택트렌즈를 제거하시오. 계속 씻으시오.",
        "line": "p2:L13"
      },
      {
        "code": "P308+P313",
        "type": "대응",
        "text": "노출 또는 접촉이 우려되면 의학적인 조언·주의를 받으시오.",
        "line": "p2:L14"
      },
      {
        "code": "P307+P311",
        "type": "대응",
        "text": "노출되면 의료기관(의사)의 도움을 받으시오.",
        "line": "p2:L15"
      },
      {
        "code": "P314",
        "type": "대응",
        "text": "불편함을 느끼면 의학적인 조치·조언을 구하시오.",
        "line": "p2:L16"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "밀봉하여 저장하시오.",
        "line": "p2:L17"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "(관련 법규에 명시된 내용에 따라) 내용물·용기를 폐기하시오.",
        "line": "p2:L18"
      }
    ],
    "nfpa": {
